// Custom sampler stubs (mapped to noise texture)
#define sampler_stoy_london sampler_noise_lq
#define sampler_grace sampler_noise_lq
// BigWings + IkeC - Heartfelt / https://www.shadertoy.com/view/ltffzl
// Transpiled to HLSL using Milkwave
#define tx sin(uTime)*0.5+1 // 0.5 <= tx <= 1.5
// CONV: setting iChannel samplers to default noise texture
#define iChannel0 sampler_stoy_london
//#define iChannel0 sampler_grace
sampler iChannel0;
// CONV: adding helper functions
float mod_conv(float x, float y) { return x - y * floor(x / y); }
vec2 mod_conv(vec2 x, vec2 y) { return x - y * floor(x / y); }
vec3 mod_conv(vec3 x, vec3 y) { return x - y * floor(x / y); }
vec4 mod_conv(vec4 x, vec4 y) { return x - y * floor(x / y); }
#define S(a, b, t) smoothstep(a, b, t)
#define HAS_HEART
#define USE_POST_PROCESSING
#define stime 70
//#define stime 110
#define stimetotal 1.2*stime
vec3 N13(float p) {
vec3 p3 = fract(vec3(p,p,p) * vec3(.1031,.11369,.13787));
p3 += dot(p3, p3.yzx + 19.19);
return fract(vec3((p3.x + p3.y)*p3.z, (p3.x+p3.z)*p3.y, (p3.y+p3.z)*p3.x));
}
vec4 N14(float t) {
return fract(sin(t*vec4(123., 1024., 1456., 264.))*vec4(6547., 345., 8799., 1564.));
}
float N(float t) {
return fract(sin(t*12345.564)*7658.76);
}
float Saw(float b, float t) {
return S(0., b, t)*S(1., b, t);
}
vec2 DropLayer2(vec2 uv_conv,  float t) {
vec2 UV = uv_conv;
uv_conv.y += t*0.75;
vec2 a = vec2(6., 1.);
vec2 grid = a*2.;
vec2 id = floor(uv_conv*grid);
float colShift = N(id.x);
uv_conv.y += colShift;
id = floor(uv_conv*grid);
vec3 n = N13(id.x*35.2+id.y*2376.1);
vec2 st = fract(uv_conv*grid)-vec2(.5, 0.0 );
float x = n.x-.5;
float y = UV.y*20.;
float wiggle = sin(y+sin(y));
x += wiggle*(.5-abs(x))*(n.z-.5);
x *= .7;
float ti = fract(t+n.z);
y = (Saw(.85, ti)-.5)*.9+.5;
vec2 p = vec2(x, y);
float d = length((st-p)*a.yx);
float mainDrop = S(.4, .0, d);
float r = sqrt(S(1., y, st.y));
float cd = abs(st.x-x);
float trail = S(.23*r, .15*r*r, cd);
float trailFront = S(-.02, .02, st.y-y);
trail *= trailFront*r*r;
y = UV.y;
float trail2 = S(.2*r, .0, cd);
float droplets = max(0., (sin(y*(1.-y)*120.)-st.y))*trail2*trailFront*n.z;
y = fract(y*10.)+(st.y-.5);
float dd = length(st-vec2(x, y));
droplets = S(.3, 0., dd);
float m = mainDrop+droplets*r*trailFront;
return vec2(m, trail);
}
float StaticDrops(vec2 uv_conv,  float t) {
uv_conv *= 40.;
vec2 id = floor(uv_conv);
uv_conv = fract(uv_conv)-.5;
vec3 n = N13(id.x*107.45+id.y*3543.654);
vec2 p = (n.xy-.5)*.7;
float d = length(uv_conv-p);
float fade = Saw(.025, fract(t+n.z));
float c = S(.3, 0., d)*fract(n.z*10.)*fade;
return c;
}
vec2 Drops(vec2 uv_conv,  float t, float l0, float l1, float l2) {
float s = StaticDrops(uv_conv, t)*l0;
vec2 m1 = DropLayer2(uv_conv, t)*l1;
vec2 m2 = DropLayer2(uv_conv*1.85, t)*l2;
float c = s+m1.x+m2.x;
c = S(.3, 1., c);
return vec2(c, max(m1.y*l0, m2.y*l1));
}

void main() {
  vec3 ret = vec3(0.0);
  vec2 uv = vUv;
  vec2 uv_orig = vUvOriginal;
  float rad = vRadius;
  float ang = vAngle;
  vec4 fragColor = 0;
// CONV: Center on screen, then try some uAspect correction
uv = (uv * 2.0) - 1.0;
uv *= uAspect.xy;
// CONV: Adjust this to flip the output (±uv.x, ±uv.y)
uv = vec2(uv.x, -uv.y);
vec2 fragCoord  = uv;
//uv = (fragCoord.xy-.5*uv.xy) / uv.y;
vec2 UV = fragCoord.xy/uv.xy;
// vec2 UV = uv;
// CONV: iMouse unsupported
// vec3 M = iMouse.xyz/uv.xyz;
//vec3 M = tx;
float f = 0.3;
// drop flow speed?
vec3 M = 5;
// float T = uTime+M.x*2.;
float T;
#ifdef HAS_HEART
//T = mod_conv(uTime, 102.);
//T = mix(T, M.x*102., M.z>0.?1.:0.);
//T = mix(T, M.x*102., 0.0);
//T = mod(uTime, stime);
T=mod(uTime, stimetotal);
#endif
float t = T*.2;
// CONV: iMouse unsupported
//vec3 iMouse = vec3(sin(uTime), sin(uTime), 1.0 );
//vec3 iMouse = tx;
vec3 iMouse = 1;
float rainAmount = iMouse.z>0. ? M.y : sin(T*.05)*.3+.7;
//float rainAmount = 1;
float maxBlur = mix(3., 6., rainAmount);
float minBlur = 2.;
float story = 0.;
float heart = 0.;
#ifdef HAS_HEART
story = S(0., stime, T);
t = min(1., T/stime); // remap drop uTime so it goes slower when it freezes
t = 1.-t;
t = (1.-t*t)*stime;
// float zoom= mix(.3, 1.2, story); // slowly zoom out
float zoom= mix(.4, 1.1, story); // slowly zoom out
//uv = uv*zoom*0.2;
uv = uv*zoom*0.8;
minBlur = 4.+S(.5, 1., story)*3.; // more opaque glass towards the end
maxBlur = 6.+S(.5, 1., story)*1.5;
vec2 hv = uv-vec2(.0, -.1); // build heart
hv.x *= .5;
float s = S(stimetotal, stime, T); // heart gets smaller and fades towards the end
hv.y-=sqrt(abs(hv.x))*.5*s;
heart = length(hv);
heart = S(.4*s, .2*s, heart)*s;
rainAmount = heart; // the rain is where the heart is
maxBlur-=heart; // inside the heart slighly less foggy
vec2 uvtx=uv*0.2;
uv *= 1.5; // zoom out a bit more
t *= .25;
#else
float zoom = -cos(T*.2);
uv *= .7+zoom*.3;
#endif
UV = (UV-.5)*(.9+zoom*.1)+.5;
float staticDrops = S(-.5, 1., rainAmount)*2.;
float layer1 = S(.25, .75, rainAmount);
float layer2 = S(.0, .5, rainAmount);
vec2 c = Drops(uv, t, staticDrops, layer1, layer2);
#ifdef CHEAP_NORMALS
vec2 n = vec2(dFdx(c.x), dFdy(c.x));// cheap normals (3x cheaper, but 2 times shittier ;))
#else
vec2 e = vec2(.001, 0.);
float cx = Drops(uv+e, t, staticDrops, layer1, layer2).x;
float cy = Drops(uv+e.yx, t, staticDrops, layer1, layer2).x;
vec2 n = vec2(cx-c.x, cy-c.x); // expensive normals
#endif
#ifdef HAS_HEART
// drop fading?
n *= 1.-S(60., 85., T);
c.y *= 1.-S(80., 100., T)*.8;
#endif
float focus = mix(maxBlur-c.y, minBlur, S(.1, .2, c.x));
// vec3 col = textureLod(iChannel0, UV+n, focus).rgb;
// vec3 col = iChannel0.SampleLevel(sampler0, UV + n, focus).rgb;
// vec3 col = textureLod4(iChannel0, vec4(uv+n, 0.0 , focus)).rgb;
// vec3 col = textureLod4(iChannel0, vec4(uv+n, 0.0 , focus)).rgb;
// focus=1; n=0;
//float fac = 2.5;
float facx = 2.5;
float facy = 6;
vec2 flippedUV = vec2(uvtx.x*facx+0.5, 0.5-uvtx.y*facy);
//vec2 flippedUV = vec2(UV.x+0.5, 0.5-UV.y);
vec3 col = textureLod4(iChannel0, vec4(flippedUV+n, 0.0 , focus)).rgb;
#ifdef USE_POST_PROCESSING
t = (T+3.)*.5; // make uTime sync with first lightning
float colFade = sin(t*.2)*.5+.5+story;
col *= mix(vec3(1., 1., 1.), vec3(.8, .9, 1.3), colFade); // subtle color shift
float fade = S(0., 10., T * 3.0); // fade in at the start
//float lightning = sin(t*sin(t * 10.0)); // lighting flicker
// Pseudo-random gate based on uTime
float chaos = fract(sin(floor(t * 0.5) * 12.9898) * 43758.5453); // changes every ~2s
float gate = step(0.1, chaos); // ~15% chance to allow flash
// Smooth flash shape
float flashShape = pow(max(0.0, sin(t + sin(t * 0.5))), 12.0 );
// Lightning intensity
float lightning = sin(t*sin(t * 10.0)) * (.2 * t*.065); // lighting flicker
lightning *= q1;
//lightning *= flashShape * gate;
// Composite
col *= 1.0 + lightning * fade * mix(1.0, 0.1, story * story);
/*  float lightning = sin(t * sin(t * 3.0)) * .5;
lightning *= pow(max(0., sin(t+sin(t))), 50.0 ); // lightning flash
*/
//col *= 1.+lightning*fade*mix(1., .1, story*story); // composite lightning
//col *= 1.-dot(UV-=.5, UV); // vignette
#ifdef HAS_HEART
col = mix(pow(col, vec3(1.2, 1.2, 1.2)), col, heart);
fade *= S(stimetotal, stimetotal - 5.0, T);
#endif
col *= fade; // composite start and end fade
#endif
//col = vec3(heart,heart,heart);
fragColor = vec4(col, 1.0 );
ret = fragColor;
  fragColor = vec4(ret, 1.0);
}

