float s = S(stimetotal, stime, T); // heart gets smaller and fades towards the end
hv.y-=sqrt(abs(hv.x))*.5*s;
heart = length(hv);
heart = S(.4*s, .2*s, heart)*s;
rainAmount = heart; // the rain is where the heart is
maxBlur-=heart; // inside the heart slighly less foggy
float2 uvtx=uv*0.2;
uv *= 1.5; // zoom out a bit more
t *= .25;
#else
float zoom = -cos(T*.2);
uv *= .7+zoom*.3;
#endif
UV = (UV-.5)*(.9+zoom*.1)+.5;
float staticDrops = S(-.5, 1., rainAmount)*2.;
float layer1 = S(.25, .75, rainAmount);
float layer2 = S(.0, .5, rainAmount);
float2 c = Drops(uv, t, staticDrops, layer1, layer2);
#ifdef CHEAP_NORMALS
float2 n = float2(dFdx(c.x), dFdy(c.x));// cheap normals (3x cheaper, but 2 times shittier ;))
#else
float2 e = float2(.001, 0.);
float cx = Drops(uv+e, t, staticDrops, layer1, layer2).x;
float cy = Drops(uv+e.yx, t, staticDrops, layer1, layer2).x;
float2 n = float2(cx-c.x, cy-c.x); // expensive normals
#endif
#ifdef HAS_HEART
// drop fading?
n *= 1.-S(60., 85., T);
c.y *= 1.-S(80., 100., T)*.8;
#endif
float focus = lerp(maxBlur-c.y, minBlur, S(.1, .2, c.x));
// float3 col = textureLod(iChannel0, UV+n, focus).rgb;
// float3 col = iChannel0.SampleLevel(sampler0, UV + n, focus).rgb;
// float3 col = tex2Dlod(iChannel0, float4(uv+n, 0, focus)).rgb;
// float3 col = tex2Dlod(iChannel0, float4(uv+n, 0, focus)).rgb;
// focus=1; n=0;
//float fac = 2.5;
float facx = 2.5;
float facy = 6;
float2 flippedUV = float2(uvtx.x*facx+0.5, 0.5-uvtx.y*facy);
//float2 flippedUV = float2(UV.x+0.5, 0.5-UV.y);
float3 col = tex2Dlod(iChannel0, float4(flippedUV+n, 0, focus)).rgb;
#ifdef USE_POST_PROCESSING
t = (T+3.)*.5; // make time sync with first lightning
float colFade = sin(t*.2)*.5+.5+story;
col *= lerp(float3(1., 1., 1.), float3(.8, .9, 1.3), colFade); // subtle color shift
float fade = S(0., 10., T*3); // fade in at the start
//float lightning = sin(t*sin(t*10)); // lighting flicker
// Pseudo-random gate based on time
float chaos = frac(sin(floor(t * 0.5) * 12.9898) * 43758.5453); // changes every ~2s
float gate = step(0.1, chaos); // ~15% chance to allow flash
// Smooth flash shape
float flashShape = pow(max(0.0, sin(t + sin(t * 0.5))), 12);
// Lightning intensity
float lightning = sin(t*sin(t*10)) * (.2 * t*.065); // lighting flicker
lightning *= q1;
//lightning *= flashShape * gate;
// Composite
col *= 1.0 + lightning * fade * lerp(1.0, 0.1, story * story);
/*  float lightning = sin(t * sin(t * 3.0)) * .5;
lightning *= pow(max(0., sin(t+sin(t))), 50); // lightning flash
*/
//col *= 1.+lightning*fade*lerp(1., .1, story*story); // composite lightning
//col *= 1.-dot(UV-=.5, UV); // vignette
#ifdef HAS_HEART
col = lerp(pow(col, float3(1.2, 1.2, 1.2)), col, heart);
fade *= S(stimetotal, stimetotal-5, T);
#endif
col *= fade; // composite start and end fade
#endif
//col = float3(heart,heart,heart);
fragColor = float4(col, 1);
ret = fragColor;
}

